select "rr".*, COALESCE(pi.supplier_invoice_no, sa.document_number_raw, gb.document_number_raw) as purchase_invoice_number, COALESCE(pi.supplier_invoice_date, sa.document_date, gb.document_date) as purchase_invoice_date, COALESCE(pi.supplier_name, sa.supplier_name, gb.supplier_name) as purchase_supplier_name, COALESCE(pi.supplier_gstin, sa.supplier_gstin, gb.supplier_gstin) as purchase_gstin, COALESCE(gi.document_number_clean, sa.document_number_clean) as gstr_invoice_number, COALESCE(gi.document_number_raw, sa.document_number_raw) as gstr_invoice_number_raw, COALESCE(gi.document_date, sa.document_date) as gstr_invoice_date, COALESCE(pi.supplier_gstin, sa.supplier_gstin, gi.supplier_gstin, gb.supplier_gstin) as supplier_gstin, COALESCE(pi.supplier_name, sa.supplier_name, gi.supplier_name, gb.supplier_name) as supplier_name, COALESCE(gi.taxable_value, sa.taxable_value) as gstr_taxable, COALESCE(gi.total_tax, sa.total_tax) as gstr_tax, COALESCE(gi.igst, sa.igst) as gstr_igst, COALESCE(gi.cgst, sa.cgst) as gstr_cgst, COALESCE(gi.sgst, sa.sgst) as gstr_sgst, COALESCE(gi.cess, sa.cess) as gstr_cess, COALESCE(pi.taxable_total, gb.taxable_value) as purchase_taxable, (COALESCE(pi.total_igst_amount,0)+COALESCE(pi.total_cgst_amount,0)+COALESCE(pi.total_sgst_amount,0) + COALESCE(gb.total_tax, 0)) as purchase_tax, COALESCE(pi.total_igst_amount, gb.igst) as purchase_igst, COALESCE(pi.total_cgst_amount, gb.cgst) as purchase_cgst, COALESCE(pi.total_sgst_amount, gb.sgst) as purchase_sgst, COALESCE(pi.total_cess_amount, gb.cess) as purchase_cess, COALESCE(pi.net_amount, gb.total_tax + gb.taxable_value) as purchase_invoice_total, pi.book_vchr_no as book_vchr_no, pi.book_vchr_date as book_vchr_date, COALESCE(pi.gstr_category, pi.source_section, sa.source_section, gi.source_section, gb.source_section) as gstr_category, COALESCE(gi.itc_available, sa.itc_available) as gstr2a_itc_available, COALESCE(gi.itc_eligibility, sa.itc_eligibility) as gstr2a_itc_eligibility, COALESCE(gi.itc_reason, sa.itc_reason) as gstr2a_itc_reason, COALESCE(pi.place_of_supply, gb.place_of_supply) as purchase_pos, COALESCE(gi.place_of_supply, sa.place_of_supply) as gstr2a_pos, COALESCE(rs.recon_status, 'pending') as reconciliation_status from "reconciliation_results" as "rr" left join "reconciliation_runs" as "run" on "rr"."recon_run_id" = "run"."id" left join "normalized_gstr2a_invoices" as "gi" on "rr"."gstr2a_invoice_id" = "gi"."id" left join "purchase_vouchers" as "pi" on "rr"."purchase_invoice_id" = "pi"."id" left join "normalized_gstr2a_invoices" as "sa" on "rr"."gstr2a_source_id" = "sa"."id" left join "normalized_gstr2b_invoices" as "gb" on "rr"."gstr2b_invoice_id" = "gb"."id" left join "reconciliation_status_gst2a_vs_book" as "rs" on "rr"."workspace_id" = "rs"."workspace_id" and ("rr"."purchase_invoice_id" = "rs"."book_data_id" or "rr"."gstr2a_invoice_id" = "rs"."gstr_data_id" or "rr"."gstr2a_source_id" = "rs"."book_data_id") where "rr"."workspace_id" = '8d84c307-e611-40c7-9d1d-3c04fce101fc' and "run"."run_type" in ('PURCHASE_2A', 'GSTR2A_VS_GSTR2B', 'PURCHASE_2A_VS_2B') order by "supplier_gstin" desc limit 25;
